mapper.select:
WITH paid_orders AS ( SELECT o.*, ROW_NUMBER() OVER (PARTITION BY o.user_id ORDER BY o.paid_at ASC, o.id ASC) AS rn FROM u_order o WHERE o.status = 1 ) SELECT o.id, o.order_no, o.user_id, u.nickname, u.email, o.plan_key, o.cycle, o.amount, o.status, o.payment_method, o.third_party_trade_id, o.paid_at, o.refunded_at, o.refund_reason, o.admin_remark, o.operator_id, o.created_at FROM paid_orders o LEFT JOIN u_user u ON u.id = o.user_id AND u.is_deleted = 0 WHERE 1 = 1
AND o.rn = 1 AND o.rn > 1
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR o.order_no LIKE CONCAT('%', #{keyword}, '%'))
AND o.plan_key = #{planKey}
AND o.cycle = #{cycle}
AND o.paid_at >= CONCAT(#{startDate}, ' 00:00:00')
AND o.paid_at <= CONCAT(#{endDate}, ' 23:59:59')
ORDER BY o.paid_at DESC LIMIT #{offset}, #{size}
